const inp = $input.item.json;
const question = inp.question || inp['Вопрос'] || '';
const MAP = [
    {match: "А можно оплатить курс в ", kb_id: "kb1", kb_text: "kb1 · Оплата: Курс оплачивается на сайте по ссылке в личном кабинете (карта, Робокасса) или наличными на ресепшене при личном визите. Рассрочка не предусмотрена.", kb_keyword: "рассрочк", kb_keyword_pattern: null, kb_numbers: []},
    {match: "Правда что оплатить можн", kb_id: "kb1", kb_text: "kb1 · Оплата: Курс оплачивается на сайте по ссылке в личном кабинете (карта, Робокасса) или наличными на ресепшене при личном визите. Рассрочка не предусмотрена.", kb_keyword: "ресепшен", kb_keyword_pattern: null, kb_numbers: []},
    {match: "Можно ли перенести занят", kb_id: "kb2", kb_text: "kb2 · Перенос занятия: Перенести конкретное занятие можно не позднее чем за 24 часа до его начала — через личный кабинет (кнопка «Перенести») или сообщением администратору. Позже 24 часов занятие считается использованным.", kb_keyword: "24 час", kb_keyword_pattern: null, kb_numbers: ["24"]},
    {match: "Если я очень тороплюсь и", kb_id: "kb2", kb_text: "kb2 · Перенос занятия: Перенести конкретное занятие можно не позднее чем за 24 часа до его начала — через личный кабинет (кнопка «Перенести») или сообщением администратору. Позже 24 часов занятие считается использованным.", kb_keyword: "24 час", kb_keyword_pattern: null, kb_numbers: ["24"]},
    {match: "Какие документы нужны, ч", kb_id: "kb3", kb_text: "kb3 · Документы при поступлении: Нужен паспорт (копия разворота) и СНИЛС; если студенту не исполнилось 18 лет — согласие одного из родителей, бланк в личном кабинете.", kb_keyword: "СНИЛС", kb_keyword_pattern: null, kb_numbers: ["18"]},
    {match: "Если мне 18 лет, нужно с", kb_id: "kb3", kb_text: "kb3 · Документы при поступлении: Нужен паспорт (копия разворота) и СНИЛС; если студенту не исполнилось 18 лет — согласие одного из родителей, бланк в личном кабинете.", kb_keyword: "родител", kb_keyword_pattern: null, kb_numbers: ["18"]},
    {match: "Когда мне вернут деньги ", kb_id: "kb4", kb_text: "kb4 · Возврат денег: Возврат оформляется в течение 10 рабочих дней на карту, с которой была оплата. Для сумм выше 3000 рублей решение проходит через руководителя, это дольше стандартного срока.", kb_keyword: "10 рабочих дней", kb_keyword_pattern: null, kb_numbers: ["10", "3000"]},
    {match: "Правда что для крупных с", kb_id: "kb4", kb_text: "kb4 · Возврат денег: Возврат оформляется в течение 10 рабочих дней на карту, с которой была оплата. Для сумм выше 3000 рублей решение проходит через руководителя, это дольше стандартного срока.", kb_keyword: "руководител", kb_keyword_pattern: null, kb_numbers: ["10", "3000"]},
    {match: "Как мне попасть на перес", kb_id: "kb5", kb_text: "kb5 · Пересдача пропущенного занятия: Пересдачи идут каждую вторую субботу месяца, расписание публикуется в объявлениях личного кабинета за неделю.", kb_keyword: "вторую субботу", kb_keyword_pattern: "\u0432\u0442\u043e\u0440(?:\u0430\u044f|\u043e\u0439|\u0443\u044e)\\s+\u0441\u0443\u0431\u0431\u043e\u0442(?:\u0430|\u044b|\u0435|\u0443|\u043e\u0439)", kb_numbers: []},
    {match: "Пересдачи бывают по субб", kb_id: "kb5", kb_text: "kb5 · Пересдача пропущенного занятия: Пересдачи идут каждую вторую субботу месяца, расписание публикуется в объявлениях личного кабинета за неделю.", kb_keyword: "вторую субботу", kb_keyword_pattern: "\u0432\u0442\u043e\u0440(?:\u0430\u044f|\u043e\u0439|\u0443\u044e)\\s+\u0441\u0443\u0431\u0431\u043e\u0442(?:\u0430|\u044b|\u0435|\u0443|\u043e\u0439)", kb_numbers: []},
    {match: "Я пропустил занятие и не", kb_id: "kb6", kb_text: "kb6 · Пропуск без предупреждения: Занятие считается проведённым, бесплатного повтора не предусмотрено — действует то же правило, что и перенос позже 24 часов.", kb_keyword: "повтор", kb_keyword_pattern: null, kb_numbers: ["24"]},
    {match: "Если я просто не пришёл ", kb_id: "kb6", kb_text: "kb6 · Пропуск без предупреждения: Занятие считается проведённым, бесплатного повтора не предусмотрено — действует то же правило, что и перенос позже 24 часов.", kb_keyword: "провед", kb_keyword_pattern: null, kb_numbers: ["24"]},
    {match: "Когда появится сертифика", kb_id: "kb7", kb_text: "kb7 · Сертификат: Электронный сертификат формируется автоматически и появляется в личном кабинете в течение 5 рабочих дней после последнего занятия курса.", kb_keyword: "5 рабочих дней", kb_keyword_pattern: null, kb_numbers: ["5"]},
    {match: "Сертификат приходит на п", kb_id: "kb7", kb_text: "kb7 · Сертификат: Электронный сертификат формируется автоматически и появляется в личном кабинете в течение 5 рабочих дней после последнего занятия курса.", kb_keyword: "кабинет", kb_keyword_pattern: null, kb_numbers: ["5"]},
    {match: "Хочу перейти на другой к", kb_id: "kb8", kb_text: "kb8 · Перевод на другой курс: Перевод возможен при наличии мест на новом курсе; разница в стоимости пересчитывается администратором индивидуально.", kb_keyword: "перевод", kb_keyword_pattern: null, kb_numbers: []},
    {match: "Если новый курс дешевле,", kb_id: "kb8", kb_text: "kb8 · Перевод на другой курс: Перевод возможен при наличии мест на новом курсе; разница в стоимости пересчитывается администратором индивидуально.", kb_keyword: "пересчит", kb_keyword_pattern: null, kb_numbers: []},
    {match: "Центр работает в государ", kb_id: "kb9", kb_text: "kb9 · Работа в праздники: Центр не работает в государственные праздники РФ, занятия на эти даты переносятся автоматически, уведомление приходит в личный кабинет.", kb_keyword: "праздник", kb_keyword_pattern: null, kb_numbers: []},
    {match: "Если праздник выпадает н", kb_id: "kb9", kb_text: "kb9 · Работа в праздники: Центр не работает в государственные праздники РФ, занятия на эти даты переносятся автоматически, уведомление приходит в личный кабинет.", kb_keyword: "автоматич", kb_keyword_pattern: null, kb_numbers: []},
    {match: "Как связаться с преподав", kb_id: "kb10", kb_text: "kb10 · Связь с преподавателем: Написать конкретному преподавателю можно через раздел «Сообщения» личного кабинета, ответ приходит в течение одного рабочего дня.", kb_keyword: "Сообщения", kb_keyword_pattern: null, kb_numbers: []},
    {match: "Можно написать в общий ч", kb_id: "kb10", kb_text: "kb10 · Связь с преподавателем: Написать конкретному преподавателю можно через раздел «Сообщения» личного кабинета, ответ приходит в течение одного рабочего дня.", kb_keyword: "Сообщения", kb_keyword_pattern: null, kb_numbers: []}
];
let picked = null;
for (const m of MAP) { if (question.includes(m.match)) { picked = m; break; } }
if (!picked) picked = MAP[0];
return { json: {
  question,
  kb_id: picked.kb_id, kb_text: picked.kb_text, kb_keyword: picked.kb_keyword,
  kb_keyword_pattern: picked.kb_keyword_pattern,
  kb_numbers: picked.kb_numbers,
  attempt: inp.attempt || 1,
  prev_answer: inp.prev_answer || '', reason: inp.reason || '',
} };

parameters.text:
=Ты — ассистент поддержки учебного центра. Вот точный пункт базы знаний, на который должен опираться ответ:

{{ $json.kb_text }}

Вопрос клиента: {{ $json.question }}

Напиши короткий ответ клиенту. СТРОГИЕ требования:
1. Не длиннее 280 символов.
2. Явно включи деталь: «{{ $json.kb_keyword }}».
3. Укажи, куда обращаться дальше — администратор, личный кабинет, преподаватель, сотрудник или руководитель.
4. Не используй никаких чисел, кроме тех, что есть в приведённом пункте базы.
5. Пиши полностью на русском языке — никакой латиницы и иероглифов.

{{ $json.prev_answer ? ('Предыдущая попытка не прошла проверку: «' + $json.prev_answer + '». Причина: ' + $json.reason + '. Исправь именно эту проблему, остальные требования сохрани.') : '' }}

parameters.jsCode:
const kb = $('Pick KB item').item.json;
const answer = $('Generate answer').item.json.text || '';
const reasons = [];
if (answer.length > 280) reasons.push('длиннее 280 символов');
// Починка 2026-10-26 (kb5, см. README): точное includes() не распознаёт склонение.
// Если для этого вопроса задан kb_keyword_pattern — проверяем regex'ом (толерантно
// к падежу), иначе — как раньше, точной подстрокой. Остальные 5 вопросов
// kb_keyword_pattern не имеют и продолжают идти через includes() без изменений.
let hasKeyword;
if (kb.kb_keyword_pattern) {
  hasKeyword = new RegExp(kb.kb_keyword_pattern, 'i').test(answer);
} else {
  hasKeyword = answer.toLowerCase().includes(kb.kb_keyword.toLowerCase());
}
if (!hasKeyword) reasons.push('нет детали «' + kb.kb_keyword + '»');
const contacts = ["администратор", "личный кабинет", "преподавател", "сотрудник", "руководител"];
if (!contacts.some(c => answer.toLowerCase().includes(c)))
  reasons.push('не указано, куда обращаться дальше');
const nums = answer.match(/\d+/g) || [];
const allowed = new Set(kb.kb_numbers);
const badNums = nums.filter(n => !allowed.has(n));
if (badNums.length) reasons.push('числа не из базы: ' + badNums.join(','));
if (/[A-Za-z]/.test(answer)) reasons.push('есть латиница');
if (/[\u4e00-\u9fff]/.test(answer)) reasons.push('есть иероглифы');
const ok = reasons.length === 0;
return { json: { output: { ok, reason: reasons.join('; ') } } };
